-- Volcando estructura para tabla coa_record.certificates
CREATE TABLE IF NOT EXISTS `certificates` (
  `id_certificate` int(11) NOT NULL AUTO_INCREMENT,
  `type` varchar(50) DEFAULT NULL,
  `code` varchar(200) DEFAULT NULL,
  `order` varchar(200) DEFAULT NULL,
  `product` varchar(200) DEFAULT NULL,
  `batch` varchar(200) DEFAULT NULL,
  `consecutive_quality` varchar(200) DEFAULT NULL,
  `customer` varchar(300) DEFAULT NULL,
  `amount` varchar(200) DEFAULT NULL,
  `dispatch_date` varchar(200) DEFAULT NULL,
  `format` longtext DEFAULT NULL,
  `state` int(11) DEFAULT 1,
  `authorization_signature` varchar(200) DEFAULT NULL,
  `material_batch` varchar(500) DEFAULT NULL,
  `user_registration` varchar(200) DEFAULT NULL,
  `registration_date` timestamp NULL DEFAULT current_timestamp(),
  `user_modified` int(11) DEFAULT NULL,
  `modification_date` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id_certificate`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8;

