e="height: 50px;" contenteditable="true">--------</td>\n				</tr>\n				<tr>\n					<td colspan="2">Wilmer A. Hernández</td>\n					<td colspan="3"><div id="SignatureImage"></div></td>\n				</tr>\n				<tr>\n					<td colspan="2" rowspan="2">Nombre / Name</td>\n					<td colspan="3" rowspan="2">Firma autorizada / Authorized signature</td>\n				</tr>\n                                <tr>\n                                        <td colspan="2">FECHA DEL DESPACHO: <div id="DateDispatch" style="padding: 4px;"><input type="date" id="dispatchDate" name="dispatchDate" class="editable pending" style="border:none; outline:none; background:transparent;" value="2026-01-17"></div></td>\n                                </tr>\n			</tbody>\n		</table>\n	</div>\n\n	', 3, 'view.png', '1402-35G16,14106-35B26,5419-35H23,240401', 'Administrador/Fabian Gaona', '2026-01-13 21:49:42', NULL, NULL);

-- Volcando estructura para tabla coa_record.format
CREATE TABLE IF NOT EXISTS `format` (
  `id_format` int(11) NOT NULL AUTO_INCREMENT,
  `application` varchar(100) DEFAULT NULL,
  `record` varchar(200) DEFAULT NULL,
  `name` varchar(250) DEFAULT NULL,
  `version` int(11) DEFAULT NULL,
  `template` longtext DEFAULT NULL,
  `state` int(11) DEFAULT NULL,
  `user_registration` varchar(200) DEFAULT NULL,
  `registration_date` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_format`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8;

