					<td>MAX1</td>\r\n					<td>MEAN1</td>\r\n				</tr>\r\n				<tr>\r\n					<td class="text-end">2.1.2</td>\r\n					<td class="text-start">Ancho / Flat Width</td>\r\n					<td>mm</td>\r\n					<td>PRM2</td>\r\n					<td>MIN2</td>\r\n					<td>MAX2</td>\r\n					<td>MEAN2</td>\r\n				</tr>\r\n				<tr>\r\n					<td class="text-end">2.1.3</td>\r\n					<td class="text-start">Espesor de pared Doble / Double Wall Thickness</td>\r\n					<td>mm</td>\r\n					<td>PRM3</td>\r\n					<td>MIN3</td>\r\n					<td>MAX3</td>\r\n					<td>MEAN3</td>\r\n				</tr>\r\n				<tr>\r\n					<td class="text-end">2.1.4</td>\r\n					<td class="text-start">Espesor pared sencilla / Single wall thickness</td>\r\n					<td>mm</td>\r\n					<td>PRM4</td>\r\n					<td>MIN4</td>\r\n					<td>MAX4</td>\r\n					<td>MEAN4</td>\r\n				</tr>\r\n				<!-- DUCTO INTERNO --> \r\n				<tr>\r\n					<td>2.2</td>\r\n					<td class="fw-bold">DUCTO INTERNO / INTERNAL TUBE</td>\r\n					<td colspan="5"></td>\r\n				</tr>\r\n				<tr>\r\n					<td class="text-end">2.2.1</td>\r\n					<td class="text-start">Diámetro exterior / External Diameter</td>\r\n					<td>mm</td>\r\n					<td>PRM5</td>\r\n					<td>MIN5</td>\r\n					<td>MAX5</td>\r\n					<td>MEAN5</td>\r\n				</tr>\r\n				<tr>\r\n					<td class="text-end">2.2.2</td>\r\n					<td class="text-start">Diámetro interior / Internal Diameter</td>\r\n					<td>mm</td>\r\n					<td>PRM6</td>\r\n					<td>MIN6</td>\r\n					<td>MAX6</td>\r\n					<td>MEAN6</td>\r\n				</tr>\r\n				<tr>\r\n					<td class="text-end">2.2.3</td>\r\n					<td class="text-start">Longitud / Length</td>\r\n					<td>mm</td>\r\n					<td>PRM7</td>\r\n					<td>MIN7</td>\r\n					<td>MAX7</td>\r\n					<td>MEAN7</td>\r\n				</tr>\r\n				<!-- DUCTO EXTERNO --> \r\n				<tr>\r\n					<td>2.3</td>\r\n					<td class="fw-bold">DUCTO EXTERNO / EXTERNAL TUBE</td>\r\n					<td colspan="5"></td>\r\n				</tr>\r\n				<tr>\r\n					<td class="text-end">2.3.1</td>\r\n					<td class="text-start">Diámetro exterior / External Diameter</td>\r\n					<td>mm</td>\r\n					<td>PRM8</td>\r\n					<td>MIN8</td>\r\n					<td>MAX8</td>\r\n					<td>MEAN8</td>\r\n				</tr>\r\n				<tr>\r\n					<td class="text-end">2.3.2</td>\r\n					<td class="text-start">Diámetro interior / Internal Diameter</td>\r\n					<td>mm</td>\r\n					<td>PRM9</td>\r\n					<td>MIN9</td>\r\n					<td>MAX9</td>\r\n					<td>MEAN9</td>\r\n				</tr>\r\n				<tr>\r\n					<td class="text-end">2.3.3</td>\r\n					<td class="text-start">Longitud / Length</td>\r\n					<td>mm</td>\r\n					<td>PRM10</td>\r\n					<td>MIN10</td>\r\n					<td>MAX10</td>\r\n					<td>MEAN10</td>\r\n				</tr>\r\n				\r\n				<!-- SOLDADURAS / WELDS --> \r\n				<tr>\r\n					<td>2.4</td>\r\n					<td class="fw-bold">SOLDADURAS / WELDS</td>\r\n					<td colspan="5"></td>\r\n				</tr>\r\n				<tr>\r\n					<td class="text-end">2.4.1</td>\r\n					<td class="text-start">Espesor zona boca / Lower weld thickness</td>\r\n					<td>mm</td>\r\n					<td>PRM11</td>\r\n					<td>MIN11</td>\r\n					<td>MAX11</td>\r\n					<td>MEAN11</td>\r\n				</tr>\r\n				<tr>\r\n					<td class="text-end">2.4.2</td>\r\n					<td class="text-start">Espesor zona cola / Upper weld thickness</td>\r\n					<td>mm</td>\r\n					<td>PRM12</td>\r\n					<td>MIN12</td>\r\n					<td>MAX12</td>\r\n					<td>MEAN12</td>\r\n				</tr>\r\n				<!-- 4.OTRAS PRUEBAS --> \r\n				<tr class="table-secondary fw-bold">\r\n					<td colspan="2">3. OTRAS PRUEBAS</td>\r\n					<td colspan="4">NORMA INTERNA</td>\r\n					<td>APROBADO</td>\r\n				</tr>\r\n				<tr class="table-secondary fw-bold">\r\n					<td colspan="2">OTHER TESTS</td>\r\n					<td colspan="4">INTERNAL STANDARD</td>\r\n					<td>APROVED</td>\r\n				</tr>\r\n				<tr>\r\n					<td>3.1</td>\r\n					<td class="text-start">Prueba Rasgado / Tear off test</td>\r\n					<td colspan="4">I-GC-015</td>\r\n					<td><input type="checkbox" checked> Ok.</td>\r\n				</tr>\r\n				<tr>\r\n					<td>3.2</td>\r\n					<td class="text-start">Prueba Estallido / Burst Test</td>\r\n					<td colspan="4">I-GC-015</td>\r\n					<td>