                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       \r\n                                                                        DECLARACION DE CUMPLIMIENTO / COMPLIANCE STATEMENT Plastitec declara que el material subministrado fue manufacturado de acuerdo a los procedimientos aprobados, usando materias primas aprobadas, cumpliendo el criterio de control de proceso aprobado y cumpliendo con los requerimientos establecidos en las especificaciones de FMCNA/Plastitec declares that the supplied material was manufactured in accordance with approved procedures, using approved raw materials, meeting the approved process control criteria and  the requirements established in the FMCNA specifications.</td>\r\n					<td colspan="5" style="height: 50px;"  contenteditable="true">------------</td>\r\n				</tr>\r\n				<tr>\r\n					<td colspan="2">Wilmer A. Hernández</td>\r\n					<td colspan="3"><div id="SignatureImage"></div></td>\r\n				</tr>\r\n				<tr>\r\n					<td colspan="2" rowspan="2">Nombre / Name</td>\r\n					<td colspan="3" rowspan="2">Firma autorizada / Authorized signature</td>\r\n				</tr>\r\n                                <tr>\r\n                                        <td colspan="2">FECHA DEL DESPACHO:<div id="DateDispatch"><span class=\'editable\' contenteditable=\'true\'>___________</span></div></td>\r\n                                </tr>\r\n					</tbody>\r\n				</table>\r\n			</div>\r\n		</body>', 1, 'Administrador', '2025-11-24 14:43:33');

-- Volcando estructura para tabla coa_record.novelty
CREATE TABLE IF NOT EXISTS `novelty` (
  `id_novelty` int(11) NOT NULL AUTO_INCREMENT,
  `id_certificate` int(11) DEFAULT NULL,
  `category` varchar(100) DEFAULT NULL,
  `description` varchar(300) DEFAULT NULL,
  `user_registration` varchar(200) DEFAULT NULL,
  `registration_date` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_novelty`),
  KEY `FK_certificate` (`id_certificate`),
  CONSTRAINT `FK_certificate` FOREIGN KEY (`id_certificate`) REFERENCES `certificates` (`id_certificate`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8;

