DELETE FROM `setting`;
INSERT INTO `setting` (`id_setting`, `categorie`, `value`, `description`, `state`, `date_register`) VALUES
	(1, 'SeverAdminitradorUsuarios', '[root][HIT1v0][172.16.5.99:3306/administracion_usuarios]', 'Consulta SQL para la base de datos de administración de usuarios', 1, '2025-09-26 14:45:54'),
	(2, 'ServerRegistrosLab', '[root][muG1Bu][172.16.1.138:3306/registro_laboratorio_va094705]', 'Consulta SQL para la base de datos de Registros LAB', 1, '2025-09-30 15:12:20'),
	(3, 'ServerSQLServerFactory', '[sa][plast][172.16.2.116:1433;databaseName=EMP001_FACT]', 'Consulta SQL Server Conexion Factory', 1, '2025-10-06 16:05:40'),
	(4, 'ServerGeneracionLotes', '[root][HIT1v0][172.16.5.99:3306/generacion_de_lotes]', 'Consulta SQL para la base de datos de Generacion Lotes', 1, '2025-10-06 16:11:10'),
	(5, 'R-GC-046', '[\'Longitud Total\',\'Ancho de manga\',\'Pared doble\',\'Pared sencilla\',\'Dia. Ext. ducto derecho\',\'Dia. Int. ducto derecho\',\'Ducto derecho\',\'Dia. Ext. ducto izquierdo\',\'Dia. Int. ducto izquierdo\',\'Ducto izquierdo\',\'Dia. Ext. ducto central\',\'Dia. Int. ducto central\',\'Ducto central\']', '[ORDER BY CASE lc.comparador\r\n    WHEN \'Longitud Total\' THEN 1\r\n    WHEN \'Ancho de manga\' THEN 2\r\n    WHEN \'Pared doble\' THEN 3\r\n    WHEN \'Pared sencilla\' THEN 4\r\n    WHEN \'Dia. Ext. ducto derecho\' THEN 5\r\n    WHEN \'Dia. Int. ducto derecho\' THEN 6\r\n    WHEN \'Ducto derecho\' THEN 7\r\n    WHEN \'Dia. Ext. ducto izquierdo\' THEN 8\r\n    WHEN \'Dia. Int. ducto izquierdo\' THEN 9\r\n    WHEN \'Ducto izquierdo\' THEN 10\r\n    WHEN \'Dia. Ext. ducto central\' THEN 11\r\n    WHEN \'Dia. Int. ducto central\' THEN 12\r\n    WHEN \'Ducto central\' THEN 13\r\nEND;]', 1, '2025-10-06 20:08:59'),
	(6, 'R-GC-046-Ficha', 'SELECT \r\n    17 as "Cant",\r\n    CONCAT(f.long_cuerpo_sellado, " +/- ", f.long_cuerpo_sellado_min) AS "Longitud Total",\r\n    CONCAT(f.ancho_manga, " +/- ", f.ancho_manga_min) AS "Ancho de manga",\r\n    CONCAT(f.pared_doble, " +/- ", f.pared_doble_min) AS "Pared doble",\r\n    CONCAT(f.pared_sencilla, " +/- ", f.pared_sencilla_min) AS "Pared sencilla",\r\n    CONCAT(f.diametro_etr_ducto_drc, " +/- ", f.diametro_etr_ducto_drc_min) AS "Dia. Ext. ducto derecho",\r\n    CONCAT(f.diametro_itr_ducto_drc, " +/- ", f.diametro_itr_ducto_drc_min) AS "Dia. Int. ducto derecho",\r\n    CONCAT(f.ducto_drc_long, " +/- ", f.ducto_drc_long_min) AS "Ducto derecho",\r\n    CONCAT(f.diametro_etr_ducto_iqe, " +/- ", f.diametro_etr_ducto_iqe_min) AS "Dia. Ext. ducto izquierdo",\r\n    CONCAT(f.diametro_itr_ducto_iqe, " +/- ", f.diametro_itr_ducto_iqe_min) AS "Dia. Int. ducto izquierdo",\r\n    CONCAT(f.ducto_iqe_long, " +/- ", f.ducto_iqe_long_min) AS "Ducto izquierdo",\r\n    CONCAT(f.diametro_etr_ducto_ctl, " +/- ", f.diametro_etr_ducto_ctl_min) AS "Dia. Ext. ducto central",\r\n    CONCAT(f.diametro_itr_ducto_ctl, " +/- ", f.diametro_itr_ducto_ctl_min) AS "Dia. Int. ducto central",\r\n    CONCAT(f.ducto_ctl_long, " +/- ", f.ducto_ctl_long_min) AS "Ducto central",\r\n    CONCAT(f.prm_sellado_bocas, " +/- ", f.prm_sellado_bocas_min) AS "Soldadura bocas",\r\n    CONCAT(f.prm_sellado_colas, " +/- ", f.prm_sellado_colas_min) AS "Soldadura colas",\r\n    CONCAT(f.codigo, " V", f.version) as "Ficha Tecnica"\r\nFROM orden_produccion o\r\nINNER JOIN producto p \r\n    ON p.id_orden_produccion = o.id_orden_produccion\r\nINNER JOIN ficha_tecnica f \r\n    ON p.id_ficha_tecnica = f.id_ficha_tecnica\r\nWHERE o.numero = XorderX \r\n  AND p.codigo = "XproductX";', '.', 1, '2025-10-08 14:01:14'),
	(7, 'ServerSignature', '[root][c0b0Ma][172.16.2.117:3306/signature]', 'Consulta de conexion para traer firma digital', 1, '2025-10-15 13:14:51'),
	(8, 'R-GC-074', '[\'Longitud Total\',\'Ancho de manga\',\'Pared doble\',\'Pared sencilla\',\'Pared sencilla estriada\',\'Dia. Ext. ducto derecho\',\'Dia. Int. ducto derecho\',\'Ducto derecho\']', '[ORDER BY CASE lc.comparador\r\n    WHEN \'Longitud Total\' THEN 1\r\n    WHEN \'Ancho de manga\' THEN 2\r\n    WHEN \'Pared doble\' THEN 3\r\n    WHEN \'Pared sencilla\' THEN 4\r\n    WHEN \'Pared sencilla estriada\' THEN 5\r\n    WHEN \'Dia. Ext. ducto derecho\' THEN 6\r\n    WHEN \'Dia. Int. ducto derecho\' THEN 7\r\n    WHEN \'Ducto derecho\' THEN 8\r\nEND;]', 1, '2025-10-22 15:15:17'),
	(9, 'R-GC-074-Ficha', 'SELECT \r\n    11 as "Cant",\r\n    CONCAT(f.long_cuerpo_sellado, " +/- ", f.long_cuerpo_sellado_min) AS "Longitud Total",\r\n    CONCAT(f.ancho_manga, " +/- ", f.ancho_manga_min) AS "Ancho de manga",\r\n    CONCAT(f.pared_doble, " +/- ", f.pared_doble_min) AS "Pared doble",\r\n    CONCAT(f.pared_sencilla, " +/- ", f.pared_sencilla_min) AS "Pared sencilla",\r\n    CONCAT(f.pared_sencilla_estriada, " +/- ", f.pared_sencilla_estriada_min) AS "Pared sencilla estriada",\r\n    CONCAT(f.diametro_etr_ducto_drc, " +/- ", f.diametro_etr_ducto_drc_min) AS "Dia. Ext. ducto derecho",\r\n    CONCAT(f.diametro_itr_ducto_drc, " +/- ", f.diametro_itr_ducto_drc_min) AS "Dia. Int. ducto derecho",\r\n    CONCAT(f.ducto_drc_long, " +/- ", f.ducto_drc_long_min) AS "Ducto derecho",\r\n    CONCAT(f.prm_sellado_bocas, " +/- ", f.prm_sellado_bocas_min) AS "Soldadura bocas",\r\n    CONCAT(f.prm_sellado_colas, " +/- ", f.prm_sellado_colas_min) AS "Soldadura colas",\r\n    CONCAT(f.codigo, " V", f.version) as "Ficha Tecnica"\r\nFROM orden_produccion o\r\nINNER JOIN producto p \r\n    ON p.id_orden_produccion = o.id_orden_produccion\r\nINNER JOIN ficha_tecnica f \r\n    ON p.id_ficha_tecnica = f.id_ficha_tecnica\r\nWHERE o.numero = XorderX \r\n  AND p.codigo = "XproductX";', '.', 1, '2025-10-22 15:15:28'),
	(10, 'ServerInspeccionManga', '[root][HIT1v0][172.16.5.99:3306/inspeccion_manga]', 'Consulta SQL para la base de datos de Inspeccion Manga', 1, '2025-10-22 15:16:02'),
	(11, 'DataMail', '[smtp.zoho.com][true][587][true][aplicativo@plastitec.co][wxWmH1szhuJn]', 'Configuracion para envio de correos', 1, '2025-10-22 15:16:02'),
	(12, 'ServerSQLServerTags', '[sa][plast][172.16.2.116:1433;databaseName=TagsLogic]', 'Consulta SQL Server Conexion Factory', 1, '2025-10-06 16:05:40'),
	(13, 'R-GC-194', '[\'Longitud Total\',\'Ancho de manga\',\'Pared doble\',\'Pared sencilla\',\'Dia. Ext. ducto derecho\',\'Dia. Int. ducto derecho\',\'Ducto derecho\',\'Dia. Ext. ducto izquierdo\',\'Dia. Int. ducto izquierdo\',\'Ducto izquierdo\']', '[ORDER BY CASE lc.comparador\r\n    WHEN \'Longitud Total\' THEN 1\r\n    WHEN \'Ancho de manga\' THEN 2\r\n    WHEN \'Pared doble\' THEN 3\r\n    WHEN \'Pared sencilla\' THEN 4\r\n    WHEN \'Dia. Ext. ducto derecho\' THEN 5\r\n    WHEN \'Dia. Int. ducto derecho\' THEN 6\r\n    WHEN \'Ducto derecho\' THEN 7\r\n    WHEN \'Dia. Ext. ducto izquierdo\' THEN 8\r\n    WHEN \'Dia. Int. ducto izquierdo\' THEN 9\r\n    WHEN \'Ducto izquierdo\' THEN 10\r\nEND;]', 1, '2025-10-06 20:08:59'),
	(14, 'R-GC-194-Ficha', 'SELECT \r\n    13 as "Cant",\r\n    CONCAT(f.long_cuerpo_sellado, " +/- ", f.long_cuerpo_sellado_min) AS "Longitud Total",\r\n    CONCAT(f.ancho_manga, " +/- ", f.ancho_manga_min) AS "Ancho de manga",\r\n    CONCAT(f.pared_doble, " +/- ", f.pared_doble_min) AS "Pared doble",\r\n    CONCAT(f.pared_sencilla, " +/- ", f.pared_sencilla_min) AS "Pared sencilla",\r\n    CONCAT(f.diametro_etr_ducto_drc, " +/- ", f.diametro_etr_ducto_drc_min) AS "Dia. Ext. ducto derecho",\r\n    CONCAT(f.diametro_itr_ducto_drc, " +/- ", f.diametro_itr_ducto_drc_min) AS "Dia. Int. ducto derecho",\r\n    CONCAT(f.ducto_drc_long, " +/- ", f.ducto_drc_long_min) AS "Ducto derecho",\r\n    CONCAT(f.diametro_etr_ducto_iqe, " +/- ", f.diametro_etr_ducto_iqe_min) AS "Dia. Ext. ducto izquierdo",\r\n    CONCAT(f.diametro_itr_ducto_iqe, " +/- ", f.diametro_itr_ducto_iqe_min) AS "Dia. Int. ducto izquierdo",\r\n    CONCAT(f.ducto_iqe_long, " +/- ", f.ducto_iqe_long_min) AS "Ducto izquierdo",\r\n    CONCAT(f.prm_sellado_bocas, " +/- ", f.prm_sellado_bocas_min) AS "Soldadura bocas",\r\n    CONCAT(f.prm_sellado_colas, " +/- ", f.prm_sellado_colas_min) AS "Soldadura colas",\r\n    CONCAT(f.codigo, " V", f.version) as "Ficha Tecnica"\r\nFROM orden_produccion o\r\nINNER JOIN producto p \r\n    ON p.id_orden_produccion = o.id_orden_produccion\r\nINNER JOIN ficha_tecnica f \r\n    ON p.id_ficha_tecnica = f.id_ficha_tecnica\r\nWHERE o.numero = XorderX \r\n  AND p.codigo = "XproductX";', '.', 1, '2025-10-08 14:01:14'),
	(15, 'BatchRecordLAB', 'SELECT "Link registro" as "Type", t.tipo_registro as "TypeReg" ,CONCAT(r.fecha_turno," - ",r.turno, " - ", l.nombre) AS "Data" ,CONCAT("http://172.16.1.164:8084/Registros_lab/Registro?opc=",IF(t.tipo_registro = "R-PRF-056","53","27"),"&Id_registro=",r.id_registro) AS "Link",\r\nr.lote_manga_c AS "Lote Manga"\r\nFROM registro r\r\nINNER JOIN linea l ON r.id_linea = l.id_linea\r\nINNER JOIN tipo_linea t ON l.id_tipo_linea = t.id_tipo_linea\r\nINNER JOIN producto p ON r.id_producto = p.id_producto\r\nINNER JOIN orden_produccion o ON p.id_orden_produccion = o.id_orden_produccion\r\nWHERE o.numero = XOrderX AND r.lote_producto = "XBatchX"\r\n\r\nUNION  \r\n\r\nSELECT "Link Despeje"  as "Type", pl.codigo as "TypeReg" ,CONCAT(r.fecha_turno," - ",r.turno, " - ", l.nombre) AS "Data", CONCAT("http://172.16.1.164:8084/Registros_lab/Registro?opc=41&irg=",rd.id_registro) AS "link", r.lote_manga_c AS "Lote Manga"\r\nFROM registro_despeje rd \r\nINNER JOIN registro r ON rd.id_registro = r.id_registro\r\nINNER JOIN linea l ON r.id_linea = l.id_linea\r\nINNER JOIN tipo_linea t ON l.id_tipo_linea = t.id_tipo_linea\r\nINNER JOIN plantilla pl ON t.id_tipo_linea = pl.id_tipo_linea\r\nINNER JOIN producto p ON r.id_producto = p.id_producto\r\nINNER JOIN orden_produccion o ON p.id_orden_produccion = o.id_orden_produccion\r\nWHERE o.numero = XOrderX AND r.lote_producto = "XBatchX"\r\n\r\n\r\n', 'Esta consulta extrae los link de los visores de registros y despeje del aplicativo REGISTROS LAB', 1, '2025-12-18 13:07:54'),
	(16, 'BatchRecordGeneracionLotes', 'SELECT a.id_anexos,a.registro,a.nombre,a.descripcion\r\nFROM anexos a\r\nWHERE a.descripcion IN XDataBatchX', 'Esta consulta extrae los anexos subidos a Generación de lotes filtrado por el lote del material.', 1, '2025-12-19 20:17:21'),
	(17, 'BatchRecordResumen', 'SELECT \'R-GC-017\' AS \'Tipo\',r.orden AS \'Txt_orden\',r.producto AS \'Cbx_producto\',CONCAT(r.lote, \' / \', r.id_linea, \' / \',  r.ciclo) AS \'Cbx_lote\', SUBSTRING(r.fecha_inicio, 1, 10) AS \'Txt_fecha_inicio\',\r\nSUBSTRING(r.fecha_fin, 1, 10) AS \'Txt_fecha_fin\', SUBSTRING(r.fecha_inicio, 12, 5) AS \'Txt_hora_inicio\', SUBSTRING(r.fecha_fin, 12, 5) AS \'Txt_hora_fin\', r.numero_certificado AS \'Txt_numero_certificado\',\r\nr.fecha_despacho AS \'Txt_fecha_despacho\', r.datos_totales AS \'Txt_datos_totales\', r.usuario_registro AS \'Txt_usuario_responsable\', r.id_resumen AS \'Id_resumen\', CONCAT(r.numero_certificado, \' - \', l.nombre) as \'Informacion\'\r\nFROM resumen r \r\nINNER JOIN linea l ON r.id_linea = l.id_linea\r\nWHERE r.orden = XOrderX AND r.lote = \'XBatchX\'', 'Esta consulta permite consultar información de los resumenes generados desde Registros LAB por medio de la orden y lote.', 1, '2026-01-09 13:02:19');

