CREATE TABLE IF NOT EXISTS `user` (
  `id_user` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(250) DEFAULT NULL,
  `last_name` varchar(250) DEFAULT NULL,
  `document` int(11) DEFAULT NULL,
  `code` int(11) DEFAULT NULL,
  `user` varchar(200) DEFAULT NULL,
  `password` varchar(250) DEFAULT NULL,
  `id_rol` int(11) DEFAULT NULL,
  `state` int(11) DEFAULT 1,
  `signature` text DEFAULT NULL,
  `user_registration` varchar(200) DEFAULT NULL,
  `registration_date` timestamp NULL DEFAULT current_timestamp(),
  `modification_date` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_user`) USING BTREE,
  UNIQUE KEY `documento` (`document`) USING BTREE,
  KEY `FK_rol` (`id_rol`),
  CONSTRAINT `FK_rol` FOREIGN KEY (`id_rol`) REFERENCES `role` (`id_role`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8;

