-- Volcando estructura para procedimiento coa_record.Sp_clt_c_ConsultCertificatesClient
DELIMITER //
CREATE PROCEDURE `Sp_clt_c_ConsultCertificatesClient`(
	IN `ctm` VARCHAR(200)
)
SELECT c.id_certificate,
       c.type,
       c.code,
       c.consecutive_quality,
       c.customer,
       c.order,
       c.product,
       c.batch,
       c.state,
       c.registration_date,
       c.amount,
       c.dispatch_date,
       YEAR(c.registration_date) AS 'Year Generate'
FROM certificates c
WHERE 
    c.state > 2 AND c.customer = ctm
	 ORDER BY c.state ASC, c.id_certificate DESC//
DELIMITER ;

-- Volcando estructura para procedimiento coa_record.Sp_clt_c_ConsultClientGroup
DELIMITER //
CREATE PROCEDURE `Sp_clt_c_ConsultClientGroup`()
SELECT c.customer,
       c.consecutive_quality AS `Ult.Consecutivo`,
       c.`order` AS `Order`,
       c.batch AS `Batch`
FROM certificates c
JOIN (
    SELECT customer, MAX(registration_date) AS last_date
    FROM certificates
    WHERE state > 0
    GROUP BY customer
) t ON t.customer = c.customer
   AND t.last_date = c.registration_date
ORDER BY c.customer ASC//
DELIMITER ;

-- Volcando estructura para procedimiento coa_record.Sp_ctf_c_ConsultCertificates
DELIMITER //
CREATE PROCEDURE `Sp_ctf_c_ConsultCertificates`(

	IN `tpe` VARCHAR(50),

	IN `ste` INT

)
SELECT c.id_certificate,

       c.type,

       c.code,

       c.consecutive_quality,

       c.customer,

       c.order,

       c.product,

       c.batch,

       c.state,

       c.registration_date,

       c.amount,

       c.dispatch_date,

       YEAR(c.registration_date) AS 'Year Generate'

FROM certificates c

WHERE 

    -- Inicio de la validación dinámica

    (tpe IS NULL OR tpe = '' OR c.type = tpe) AND (ste IS NULL OR ste = 0 OR c.state = ste) AND c.state > 0 

    -- Fin de la validación dinámica

	 ORDER BY c.state ASC, c.id_certificate DESC//
DELIMITER ;

