-- Volcando estructura para procedimiento coa_record.Sp_nvt_r_RegisterNovelty
DELIMITER //
CREATE PROCEDURE `Sp_nvt_r_RegisterNovelty`(

	IN `IdC` INT,

	IN `IdC2` INT,

	IN `ctg` VARCHAR(100),

	IN `dpc` VARCHAR(300),

	IN `urg` VARCHAR(200),

	IN `ste` INT

)
BEGIN

    DECLARE EXIT HANDLER FOR SQLEXCEPTION

    BEGIN

        ROLLBACK;

        RESIGNAL;

    END;



    START TRANSACTION;



    INSERT INTO novelty (id_certificate, category, `description`, user_registration)

    VALUES (IdC, ctg, dpc, urg);



    UPDATE certificates

    SET state = ste

    WHERE id_certificate = IdC2;



    COMMIT;

END//
DELIMITER ;

