-- Volcando estructura para procedimiento coa_record.Sp_sta_c_ConsultAccountants
DELIMITER //
CREATE PROCEDURE `Sp_sta_c_ConsultAccountants`()
SELECT

    COUNT(CASE 

        WHEN DATE(registration_date) = CURDATE() 

        THEN 1 END) AS certificados_hoy,



    COUNT(CASE 

        WHEN YEARWEEK(registration_date, 1) = YEARWEEK(CURDATE(), 1)

        THEN 1 END) AS certificados_semana,



    COUNT(CASE 

        WHEN YEAR(registration_date) = YEAR(CURDATE())

         AND MONTH(registration_date) = MONTH(CURDATE())

        THEN 1 END) AS certificados_mes,



    COUNT(CASE 

        WHEN YEAR(registration_date) = YEAR(CURDATE())

        THEN 1 END) AS certificados_anio

FROM certificates

WHERE state > 0//
DELIMITER ;

-- Volcando estructura para procedimiento coa_record.Sp_sta_c_ConsultAmountCertificates
DELIMITER //
CREATE PROCEDURE `Sp_sta_c_ConsultAmountCertificates`()
SELECT 

    s.state AS estado,



    CASE s.state 

        WHEN 1 THEN 'info'

        WHEN 2 THEN 'warning'

        ELSE 'success'

    END AS IconColor,



    CASE s.state 

        WHEN 1 THEN 'fas fa-spinner fa-spin'

        WHEN 2 THEN 'fas fa-check'

        ELSE 'fas fa-signature'

    END AS IconClass,



    CASE s.state 

        WHEN 1 THEN 'Certificados en proceso'

        WHEN 2 THEN 'Certificados finalizados'

        ELSE 'Certificados firmados'

    END AS Categoria,



    COUNT(c.id_certificate) AS cantidad,

    

    CASE s.state 

        WHEN 1 THEN 'Generate?opt=1&Type=&StateM=1'

        WHEN 2 THEN 'Generate?opt=8&StateM=2'

        ELSE 'Generate?opt=8&StateM=3'

    END AS Link



FROM (SELECT 1 AS state UNION ALL SELECT 2 UNION ALL SELECT 3) s

LEFT JOIN certificates c 

    ON c.state = s.state

GROUP BY s.state



UNION ALL



-- 🔹 FILA TOTAL

SELECT 

    4 AS estado,

    'dark' AS IconColor,

    'fas fa-layer-group' AS IconClass,

    'Total certificados' AS Categoria,

    COUNT(id_certificate) AS cantidad,

    '#' AS Link

FROM certificates

WHERE state IN (1,2,3)



ORDER BY estado//
DELIMITER ;

-- Volcando estructura para procedimiento coa_record.Sp_sta_c_ConsultRankingCustomer
DELIMITER //
CREATE PROCEDURE `Sp_sta_c_ConsultRankingCustomer`()
SELECT 

    c.customer,

    t.total_certificados,

    c.registration_date AS ultima_fecha,

    c.consecutive_quality AS ultimo_consecutivo

FROM certificates c

JOIN (

    SELECT 

        customer,

        MAX(registration_date) AS ultima_fecha

    FROM certificates

    GROUP BY customer

) u 

    ON c.customer = u.customer

   AND c.registration_date = u.ultima_fecha

JOIN (

    SELECT 

        customer,

        COUNT(id_certificate) AS total_certificados

    FROM certificates

    GROUP BY customer

) t 

    ON c.customer = t.customer

GROUP BY c.customer

ORDER BY c.registration_date DESC

LIMIT 5//
DELIMITER ;

-- Volcando estructura para procedimiento coa_record.Sp_sta_c_ConsultStatistics
DELIMITER //
CREATE PROCEDURE `Sp_sta_c_ConsultStatistics`()
BEGIN

    SET lc_time_names = 'es_ES';



    SELECT 

        DATE_FORMAT(registration_date, '%Y-%m') AS mes_key,

        DATE_FORMAT(registration_date, '%M') AS mes_nombre,

        COUNT(id_certificate) AS total_certificados

    FROM certificates

    WHERE registration_date >= DATE_SUB(CURDATE(), INTERVAL 6 MONTH)

      AND state > 0

    GROUP BY mes_key, mes_nombre

    ORDER BY mes_key ASC;

END//
DELIMITER ;

-- Volcando estructura para procedimiento coa_record.Sp_sta_c_ConsultUltimateCertificate
DELIMITER //
CREATE PROCEDURE `Sp_sta_c_ConsultUltimateCertificate`()
SELECT c.consecutive_quality,c.customer,CASE c.state WHEN 1 THEN 'En proceso' WHEN 2 THEN 'Finalizados' ELSE 'Firmado' END AS 'Estado',

CASE c.state 

	WHEN 1 THEN CONCAT('Generate?opt=1&Type=&IdCertificate=',c.id_certificate) 

	WHEN 2 THEN CONCAT('Generate?opt=8&IdCertificate=',c.id_certificate) 

	ELSE CONCAT('Generate?opt=8&IdCertificate=',c.id_certificate)  END AS 'Link'

FROM certificates c 

WHERE c.state > 0

ORDER BY c.id_certificate desc

LIMIT 5//
DELIMITER ;

