-- Volcando estructura para procedimiento coa_record.Sp_usr_c_ConsultUserId
DELIMITER //
CREATE PROCEDURE `Sp_usr_c_ConsultUserId`(

	IN `IdU` int

)
SELECT u.id_user,u.`name`,u.last_name,u.document,u.`code`,u.`user`,u.`password`,u.state,u.signature,u.user_registration,u.registration_date,u.modification_date

FROM user u 

WHERE u.id_user = IdU//
DELIMITER ;

-- Volcando estructura para procedimiento coa_record.Sp_usr_c_ConsultUserPassword
DELIMITER //
CREATE PROCEDURE `Sp_usr_c_ConsultUserPassword`(

	IN `usr` VARCHAR(100),

	IN `psw` VARCHAR(100)

)
SELECT u.id_user,CONCAT(u.`name`,' ',u.last_name),u.document,u.`code`,u.`user`,u.`password`,



				u.id_rol, r.role_name,



				IF(u.`password` = YEAR(CURDATE()) OR CHAR_LENGTH(u.`password`) < 30, 'YES',  'NO') AS 'CountCaracter',



				u.`name`,u.`password`,u.state,u.user_registration,u.registration_date,r.permission,u.signature



FROM user u



INNER JOIN role r ON u.id_rol = r.id_role



WHERE u.`user` = usr AND u.`password` = psw//
DELIMITER ;

-- Volcando estructura para procedimiento coa_record.Sp_usr_c_ConsultUsers
DELIMITER //
CREATE PROCEDURE `Sp_usr_c_ConsultUsers`()
SELECT u.id_user, u.name, u.last_name, u.document, u.code, u.`user`, u.`password`, u.id_rol, r.role_name, u.state, u.user_registration, u.registration_date



FROM USER u



INNER JOIN role r ON u.id_rol = r.id_role



ORDER BY u.state DESC//
DELIMITER ;

-- Volcando estructura para procedimiento coa_record.Sp_usr_c_ConsultUsuarRestarPass
DELIMITER //
CREATE PROCEDURE `Sp_usr_c_ConsultUsuarRestarPass`(

	IN `dcm` INT,

	IN `usr` VARCHAR(100)

)
SELECT u.id_user,u.name, u.last_name, u.document, u.code, u.`user`, u.`password`, u.id_rol, r.role_name, u.state, u.user_registration, u.registration_date



FROM user u 



INNER JOIN role r ON u.id_rol = r.id_role



WHERE u.document = dcm AND u.`user` = usr//
DELIMITER ;

